import { db } from "@/lib/db";
import { getSettingBool } from "@/lib/settings";
import { nxeonConnectionKeys } from "@/lib/server-directory-data";
import { fetchValveList, VALVE_APPIDS, ValveFetchError, type ExternalCandidate } from "./valve";

/**
 * Ingest one game from the Steam master list into ExternalServer. Gated:
 * `apply` writes only when Setting directory_ingest_enabled is true. Dry run
 * (default) fetches + counts and writes nothing.
 *
 * Dedupe at the door: a candidate whose connection (host:port or ip:port)
 * equals something Nxeon hosts is dropped — the directory shows OUR entry
 * (with the Nxeon badge), not a duplicate. Candidates already stored under the
 * same connKey from another source row are skipped too. Rows not seen for
 * PRUNE_AFTER_DAYS are deleted so a dead server does not linger.
 */
export const PRUNE_AFTER_DAYS = 3;

export type IngestResult = { game: string; fetched: number; inserted: number; updated: number; duplicates: number; pruned: number; dryRun: boolean };

export function splitDuplicates<T extends { connKey: string; ipKey: string | null }>(cands: T[], nxeonKeys: Set<string>): { keep: T[]; dup: number } {
  const seen = new Set<string>();
  const keep: T[] = [];
  let dup = 0;
  for (const c of cands) {
    const keys = [c.connKey, ...(c.ipKey ? [c.ipKey] : [])];
    if (keys.some((k) => nxeonKeys.has(k) || seen.has(k))) { dup++; continue; }
    keys.forEach((k) => seen.add(k));
    keep.push(c);
  }
  return { keep, dup };
}

export async function ingestValveGame(game: string, opts: { apply: boolean; key: string; limit?: number; fetchImpl?: typeof fetch }): Promise<IngestResult> {
  if (!VALVE_APPIDS[game]) throw new Error(`Unsupported game for the Steam list: ${game}`);
  if (opts.apply && !(await getSettingBool("directory_ingest_enabled", false))) {
    throw new Error("Ingestion is switched off (Setting directory_ingest_enabled). Turn it on in /admin/directory first.");
  }
  const run = opts.apply ? await db.directoryIngestRun.create({ data: { source: "valve", game } }) : null;
  try {
    const fetched = await fetchValveList(game, { key: opts.key, limit: opts.limit, fetchImpl: opts.fetchImpl });
    const nxKeys = await nxeonConnectionKeys();
    const { keep, dup } = splitDuplicates<ExternalCandidate>(fetched, nxKeys);
    let inserted = 0, updated = 0, pruned = 0;
    if (opts.apply) {
      const existing = new Map((await db.externalServer.findMany({ where: { source: "valve", game }, select: { id: true, sourceKey: true } })).map((r) => [r.sourceKey, r.id]));
      const now = new Date();
      for (let i = 0; i < keep.length; i += 100) {
        await db.$transaction(keep.slice(i, i + 100).map((c) => {
          const data = {
            game: c.game, name: c.name, host: c.host, ip: c.ip, port: c.port, queryPort: c.queryPort, map: c.map,
            players: c.players, maxPlayers: c.maxPlayers, version: c.version, tags: c.tags,
            connKey: c.connKey, ipKey: c.ipKey, lastSeenAt: now,
          };
          if (existing.has(c.sourceKey)) updated++; else inserted++;
          return db.externalServer.upsert({
            where: { source_sourceKey: { source: "valve", sourceKey: c.sourceKey } },
            create: { source: "valve", sourceKey: c.sourceKey, ...data }, update: data,
          });
        }));
      }
      // Rows that now collide with something Nxeon hosts are removed (they were listed before we hosted them).
      const gone = await db.externalServer.deleteMany({
        where: { source: "valve", game, OR: [{ lastSeenAt: { lt: new Date(Date.now() - PRUNE_AFTER_DAYS * 86_400_000) } }, { connKey: { in: [...nxKeys] } }] },
      });
      pruned = gone.count;
      await db.directoryIngestRun.update({ where: { id: run!.id }, data: { finishedAt: new Date(), fetched: fetched.length, inserted, updated, duplicates: dup, pruned } });
    }
    return { game, fetched: fetched.length, inserted, updated, duplicates: dup, pruned, dryRun: !opts.apply };
  } catch (e) {
    const msg = e instanceof ValveFetchError ? e.message : e instanceof Error ? e.message : "ingest failed";
    if (run) await db.directoryIngestRun.update({ where: { id: run.id }, data: { finishedAt: new Date(), error: msg.slice(0, 300) } }).catch(() => {});
    throw e;
  }
}
