import "server-only";
import type { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { getSetting, getSettingBool } from "@/lib/settings";
import { gameSubdomainBase } from "@/lib/game-subdomain-dns";
import { FREEMC_GAME_TYPES } from "@/lib/free-minecraft-control";
import { customerRegionLabel } from "@/lib/node-regions";
import { listVisibleFreePublicServers, liveState, connectAddress } from "@/lib/free-public-server";
import { dedupeEntries, rankEntries, normalizeHost, connKey, type DirEntry } from "@/lib/server-directory";

/**
 * Database side of the public directory: builds `DirEntry[]` from every source
 * and applies the pure merge rules in lib/server-directory.ts. Each source is
 * read in its own try/catch so an un-migrated table (older staging DB) or a
 * failing source degrades to "none from there", never a broken page.
 *
 * PRIVACY: a paid listing carries the server's name, its owner-written text and
 * its play subdomain — never an owner, an internal id, a root password or a
 * node IP as a DISPLAYED value. (A node ip:port is used internally as a
 * dedupe key only, so a third-party list row for a server we host collapses
 * into our own entry; it is not rendered.)
 */

/** Paid servers that opted in, are running, and were not hidden by moderation. */
export const PAID_LISTING_WHERE: Prisma.ServerWhereInput = {
  publicListing: true,
  status: "RUNNING",
  gamePlan: { isNot: null },
  subdomain: { not: null },
  OR: [{ listingMeta: { is: null } }, { listingMeta: { is: { hidden: false } } }],
};

const safe = async <T,>(p: Promise<T>, fallback: T): Promise<T> => { try { return await p; } catch { return fallback; } };

async function paidEntries(): Promise<DirEntry[]> {
  const base = await gameSubdomainBase();
  const rows = await safe(db.server.findMany({
    where: PAID_LISTING_WHERE,
    select: {
      id: true, name: true, label: true, publicDescription: true, subdomain: true, createdAt: true,
      gamePlan: { select: { slots: true, gameFamily: true } },
      node: { select: { publicIp: true, region: true } },
      portForwards: { select: { publicPort: true } },
      listingMeta: { select: { tagline: true, imageUrl: true, websiteUrl: true, mediaApproved: true, featured: true } },
    },
    orderBy: { createdAt: "asc" },
  }), []);
  return rows.filter((s) => s.subdomain).map((s): DirEntry => {
    const m = s.listingMeta;
    const host = `${s.subdomain}.${base}`;
    const ip = s.node?.publicIp ? normalizeHost(s.node.publicIp) : null;
    return {
      key: `p-${s.id.slice(0, 8)}`, source: "nxeon-paid", nxeon: true,
      game: s.gamePlan?.gameFamily ?? "minecraft",
      name: s.label || s.name, tagline: m?.tagline ?? "", description: s.publicDescription ?? "",
      imageUrl: m?.mediaApproved && m.imageUrl ? m.imageUrl : null,
      address: host, host, port: null,
      alsoKeys: ip ? s.portForwards.map((f) => `${ip}:${f.publicPort}`) : [],
      players: null, maxPlayers: s.gamePlan?.slots ?? null,
      country: null, region: s.node?.region ? customerRegionLabel(s.node.region) : null,
      featured: !!m?.featured, href: null,
      websiteUrl: m?.mediaApproved && m.websiteUrl ? m.websiteUrl : null,
      seenAt: null,
    };
  });
}

async function freeMcEntries(): Promise<DirEntry[]> {
  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
  const rows = await safe(db.freeMinecraftServer.findMany({
    where: { isPublic: true, status: "READY" }, orderBy: { createdAt: "asc" },
    select: { subdomain: true, name: true, activeGameType: true, publicTagline: true, publicDescription: true },
  }), []);
  return rows.map((s): DirEntry => {
    const preset = FREEMC_GAME_TYPES[s.activeGameType] ?? FREEMC_GAME_TYPES.vanilla;
    const host = `${s.subdomain}.${domain}`;
    return {
      key: `f-${s.subdomain}`, source: "nxeon-free", nxeon: true, game: "minecraft",
      name: s.name || s.subdomain, tagline: s.publicTagline ?? "", description: s.publicDescription || preset.description,
      imageUrl: null, address: host, host, port: null, alsoKeys: [],
      players: null, maxPlayers: null, country: null, region: null, featured: false,
      href: `/servers/${s.subdomain}`, websiteUrl: null, seenAt: null,
    };
  });
}

async function communityEntries(): Promise<DirEntry[]> {
  const rows = await listVisibleFreePublicServers();
  return Promise.all(rows.map(async (c): Promise<DirEntry> => {
    const l = await liveState(c, 1200);
    return {
      key: `c-${c.slug}`, source: "nxeon-community", nxeon: true, game: c.game,
      name: c.name, tagline: c.tagline ?? "", description: "Free, public and run by Nxeon. No account needed to join.",
      imageUrl: null, address: connectAddress(c), host: c.host, port: c.port, alsoKeys: [],
      players: l.state === "online" ? l.players : null, maxPlayers: c.maxPlayers,
      country: null, region: c.region ? customerRegionLabel(c.region) : null, featured: true,
      href: `/free-${c.game}-server`, websiteUrl: null, seenAt: l.state === "online" ? l.checkedAt : null,
    };
  }));
}

async function externalEntries(game?: string): Promise<DirEntry[]> {
  if (!(await safe(getSettingBool("directory_external_show", false), false))) return [];
  const rows = await safe(db.externalServer.findMany({
    where: { hidden: false, lastSeenAt: { gte: new Date(Date.now() - 3 * 86_400_000) }, ...(game ? { game } : {}) },
    orderBy: [{ players: { sort: "desc", nulls: "last" } }, { name: "asc" }],
    take: 600,
  }), []);
  return rows.map((r): DirEntry => ({
    key: `x-${r.id.slice(0, 10)}`, source: "external", nxeon: false, game: r.game,
    name: r.name, tagline: "", description: r.description ?? (r.map ? `Map: ${r.map}` : ""),
    imageUrl: r.imageUrl, address: `${r.host}:${r.port}`, host: r.host, port: r.port,
    alsoKeys: r.ipKey ? [r.ipKey] : [],
    players: r.players, maxPlayers: r.maxPlayers, country: r.country, region: null, featured: false,
    href: null, websiteUrl: null, seenAt: r.lastSeenAt.getTime(),
  }));
}

/** Every Nxeon-hosted entry (all games), before dedupe. Also used by the ingester to avoid re-listing our own servers. */
export async function nxeonEntries(): Promise<DirEntry[]> {
  const [paid, free, comm] = await Promise.all([paidEntries(), freeMcEntries(), communityEntries()]);
  return [...paid, ...free, ...comm];
}

/** The ip:port / host:port keys of everything Nxeon hosts (for ingest-time dedupe). */
export async function nxeonConnectionKeys(): Promise<Set<string>> {
  const out = new Set<string>();
  for (const e of await nxeonEntries()) {
    out.add(connKey(e.game, e.host, e.port));
    for (const k of e.alsoKeys) out.add(k);
  }
  return out;
}

/** Merged, deduplicated, ranked directory. `game` narrows to one family. */
export async function loadDirectory(opts: { game?: string } = {}): Promise<{ entries: DirEntry[]; dropped: number }> {
  const [nx, ext] = await Promise.all([nxeonEntries(), externalEntries(opts.game)]);
  const all = [...nx, ...ext].filter((e) => !opts.game || e.game === opts.game);
  const { entries, dropped } = dedupeEntries(all);
  return { entries: rankEntries(entries), dropped };
}

  /** ms epoch the live numbers/entry were last confirmed. */
  seenAt: number | null;
};

/** Default join port per game, so `host` and `host:default` are one connection. */
export const DEFAULT_PORT: Record<string, number> = {
  minecraft: 25565, bedrock: 19132, valheim: 2456, rust: 28015, cs2: 27015, tf2: 27015, gmod: 27015,
  l4d2: 27015, cs16: 27015, projectzomboid: 16261, terraria: 7777, ark: 7777, arkasa: 7777, palworld: 8211,
  corekeeper: 0, vrising: 9876, enshrouded: 15637, factorio: 34197, conan: 7777, unturned: 27015,
  sdtd: 26900, satisfactory: 7777, dayz: 2302, squad: 7787, mordhau: 7777,
};

const IPV4 = /^\d{1,3}(?:\.\d{1,3}){3}$/;
export const isIpv4 = (h: string) => IPV4.test(h) && h.split(".").every((n) => Number(n) <= 255);

/** Lowercase, trim, drop a trailing dot, drop IPv4 leading zeros. */
export function normalizeHost(raw: string): string {
  let h = String(raw ?? "").trim().toLowerCase().replace(/\.$/, "");
  if (isIpv4(h)) h = h.split(".").map((n) => String(Number(n))).join(".");
  return h;
}

/** Canonical dedupe key for a connection. `port` null/0 = the game's default. */
export function connKey(game: string, host: string, port: number | null | undefined): string {
  const h = normalizeHost(host);
  const p = port && port > 0 ? port : DEFAULT_PORT[game] ?? 0;
  return `${h}:${p}`;
}

/**
 * Parse a connection string a person or a source typed: `host`, `host:port`,
 * `ip:port`, optionally with a `scheme://` or trailing path. Returns null when
 * it is not a plausible host. IPv6 is not listed (not joinable in these games).
 */
export function parseConnection(raw: string): { host: string; port: number | null } | null {
  let s = String(raw ?? "").trim();
  if (!s || s.length > 255) return null;
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//i, "").replace(/[/?#].*$/, "");
  const m = /^([^:\s]+)(?::(\d{1,5}))?$/.exec(s);
  if (!m) return null;
  const host = normalizeHost(m[1]);
  const port = m[2] ? Number(m[2]) : null;
  if (port != null && (port < 1 || port > 65535)) return null;
  const domain = /^(?=.{3,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$/.test(host);
  if (!domain && !isIpv4(host)) return null;
  return { host, port };
}

const imageScore = (e: DirEntry) => (e.imageUrl ? 1 : 0);
const richness = (e: DirEntry) => e.description.length + e.tagline.length;

/** Higher wins a duplicate. */
function priority(e: DirEntry): [number, number, number, number] {
  return [e.nxeon ? 1 : 0, imageScore(e), richness(e), e.seenAt ?? 0];
}
function better(a: DirEntry, b: DirEntry): boolean {
  const pa = priority(a), pb = priority(b);
  for (let i = 0; i < pa.length; i++) if (pa[i] !== pb[i]) return pa[i] > pb[i];
  return a.key < b.key; // total order: deterministic
}

export const entryKeys = (e: DirEntry): string[] => [connKey(e.game, e.host, e.port), ...e.alsoKeys.map(normalizeKey)];
function normalizeKey(k: string): string {
  const i = k.lastIndexOf(":");
  return i < 0 ? k.toLowerCase() : `${normalizeHost(k.slice(0, i))}:${k.slice(i + 1)}`;
}

/**
 * Collapse entries that share ANY connection key (union-find, so A~B and B~C
 * collapse to one). Returns survivors in input-independent order plus how many
 * were dropped. Pure and deterministic.
 */
export function dedupeEntries(entries: DirEntry[]): { entries: DirEntry[]; dropped: number } {
  const parent = entries.map((_, i) => i);
  const find = (i: number): number => (parent[i] === i ? i : (parent[i] = find(parent[i])));
  const owner = new Map<string, number>();
  entries.forEach((e, i) => {
    for (const k of entryKeys(e)) {
      const j = owner.get(k);
      if (j == null) owner.set(k, i);
      else parent[find(i)] = find(j);
    }
  });
  const groups = new Map<number, DirEntry[]>();
  entries.forEach((e, i) => {
    const r = find(i);
    (groups.get(r) ?? groups.set(r, []).get(r)!).push(e);
  });
  const out: DirEntry[] = [];
  for (const g of groups.values()) {
    let win = g[0];
    for (const e of g.slice(1)) if (better(e, win)) win = e;
    if (!win.nxeon && g.length > 1) {
      // An external survivor inherits what its duplicates know. Never done for Nxeon entries.
      const donors = g.filter((x) => x !== win && !x.nxeon);
      const img = win.imageUrl ?? donors.find((d) => d.imageUrl)?.imageUrl ?? null;
      const desc = win.description || donors.map((d) => d.description).find(Boolean) || "";
      const cc = win.country ?? donors.find((d) => d.country)?.country ?? null;
      win = { ...win, imageUrl: img, description: desc, country: cc };
    }
    out.push(win);
  }
  return { entries: out, dropped: entries.length - out.length };
}

/** Image first, then Nxeon-hosted, then busiest, then name. Featured pinned by `featuredFirst`. */
export function rankEntries(list: DirEntry[]): DirEntry[] {
  return [...list].sort((a, b) =>
    imageScore(b) - imageScore(a)
    || Number(b.nxeon) - Number(a.nxeon)
    || (b.players ?? -1) - (a.players ?? -1)
    || a.name.localeCompare(b.name)
    || (a.key < b.key ? -1 : 1));
}

/** The featured shelf: admin-featured Nxeon listings and Nxeon community servers, then Nxeon entries with an image. */
export function pickFeatured(list: DirEntry[], max = 6): DirEntry[] {
  const pool = list.filter((e) => e.nxeon && (e.featured || e.source === "nxeon-community" || e.imageUrl));
  return rankEntries(pool).sort((a, b) => Number(b.featured) - Number(a.featured)).slice(0, max);
}

export type GameGroup = { game: string; total: number; nxeon: number; players: number; withImage: number };

/** Per-game roll-up for the directory homepage (cover tiles), busiest/most-illustrated first. */
export function groupByGame(list: DirEntry[]): GameGroup[] {
  const m = new Map<string, GameGroup>();
  for (const e of list) {
    const g = m.get(e.game) ?? { game: e.game, total: 0, nxeon: 0, players: 0, withImage: 0 };
    g.total++;
    if (e.nxeon) g.nxeon++;
    if (e.imageUrl) g.withImage++;
    g.players += e.players ?? 0;
    m.set(e.game, g);
  }
  return [...m.values()].sort((a, b) => b.nxeon - a.nxeon || b.total - a.total || a.game.localeCompare(b.game));
}

/** A server counts toward indexing only when it is described and was confirmed recently. */
export const INDEX_MIN_DESCRIBED = 3;
export const INDEX_MAX_AGE_MS = 7 * 86_400_000;
export function isDescribed(e: DirEntry): boolean {
  return (e.tagline + e.description).trim().length >= 20;
}
export function indexableGamePage(list: DirEntry[], now = Date.now()): boolean {
  const ok = list.filter((e) => isDescribed(e) && (e.seenAt == null || now - e.seenAt <= INDEX_MAX_AGE_MS));
  return ok.length >= INDEX_MIN_DESCRIBED;
}

// ---------------------------------------------------------------------------
// Owner-supplied listing fields. Rejected, never sanitised: what is accepted is
// stored as typed. https only, no credentials in the URL, bounded length.
// ---------------------------------------------------------------------------
export function cleanText(raw: unknown, max: number): string | null {
  const t = String(raw ?? "")
    // eslint-disable-next-line no-control-regex
    .replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
  return t ? t.slice(0, max) : null;
}

export function validHttpsUrl(raw: unknown): { ok: true; url: string } | { ok: false; error: string } {
  const s = String(raw ?? "").trim();
  if (!s) return { ok: false, error: "empty" };
  if (s.length > 300) return { ok: false, error: "URL is too long." };
  let u: URL;
  try { u = new URL(s); } catch { return { ok: false, error: "Not a valid URL." }; }
  if (u.protocol !== "https:") return { ok: false, error: "Only https:// links are accepted." };
  if (u.username || u.password) return { ok: false, error: "Links with a username or password are not accepted." };
  const h = u.hostname.toLowerCase();
  if (!h.includes(".") || isIpv4(h) || h === "localhost" || h.endsWith(".local") || h.endsWith(".internal")) {
    return { ok: false, error: "Use a public domain name." };
  }
  return { ok: true, url: u.toString() };
}

/** Third-party list submission kit (mkt-031): the exact text an owner pastes into each list's form. */
export function submissionKit(i: { game: string; name: string; address: string; tagline: string | null; description: string | null }) {
  const text = [i.name, i.tagline, i.description].filter(Boolean).join(" - ");
  return {
    name: i.name,
    address: i.address,
    blurb: text.slice(0, 500),
    lists: [
      { id: "gamemonitoring", label: "GameMonitoring", url: "https://gamemonitoring.net/", note: "Free to list. Choose the game, paste the address, then add the blurb." },
      { id: "serverlist-gg", label: "serverlist.gg", url: "https://serverlist.gg/", note: "Free to list. Sign in, add a server and paste the address and blurb." },
    ],
  };
}

