export const dynamic = "force-dynamic";

/**
 * Moderation + settings for the public server directory (growth batch G6).
 * Customer listings are opt-in (Server.publicListing); this page reviews the
 * optional picture/website links before they render publicly, hides or features
 * a listing, and controls the third-party (Steam list) ingest. Nothing here
 * touches a VM.
 */
export default async function AdminDirectory() {
  await requireArea("fleet");
  const base = await gameSubdomainBase();
  const [ingestOn, showOn] = await Promise.all([getSettingBool("directory_ingest_enabled", false), getSettingBool("directory_external_show", false)]);
  const listed = await db.server.findMany({
    where: { publicListing: true, gamePlan: { isNot: null } },
    select: {
      id: true, name: true, label: true, subdomain: true, status: true, publicDescription: true,
      gamePlan: { select: { gameFamily: true } }, listingMeta: true,
    },
    orderBy: { createdAt: "desc" },
    take: 200,
  }).catch(() => null);
  if (listed === null) {
    return <div className="space-y-6"><PageHeader title="Server directory" sub="Moderation and settings." /><EmptyState title="Tables not migrated" sub="Run prisma db push on this database to enable the directory tools." /></div>;
  }
  const [ext, runs, extCount] = await Promise.all([
    db.externalServer.findMany({ orderBy: { lastSeenAt: "desc" }, take: 40 }).catch(() => []),
    db.directoryIngestRun.findMany({ orderBy: { startedAt: "desc" }, take: 8 }).catch(() => []),
    db.externalServer.count().catch(() => 0),
  ]);
  const pendingMedia = listed.filter((s) => s.listingMeta && (s.listingMeta.imageUrl || s.listingMeta.websiteUrl) && !s.listingMeta.mediaApproved);
  const gname = (f: string | undefined) => GAME_DISPLAY[(f ?? "minecraft") as GameFamily]?.name ?? f ?? "Game";
  return (
    <div className="space-y-6">
      <PageHeader title="Server directory" sub="Opt-in customer listings, optional pictures/links (reviewed here first) and third-party servers." />
      <div className="grid gap-4 sm:grid-cols-4">
        <StatCard label="Opted-in listings" value={String(listed.length)} />
        <StatCard label="Waiting for review" value={String(pendingMedia.length)} />
        <StatCard label="Hidden by staff" value={String(listed.filter((s) => s.listingMeta?.hidden).length)} />
        <StatCard label="Third-party rows" value={String(extCount)} />
      </div>

      <div className="grid gap-4 lg:grid-cols-2">
        <FlagSwitch flag="directory_ingest_enabled" label="Allow ingesting the Steam server list" on={ingestOn}
          help="Lets scripts/directory-ingest.ts --apply write rows. The Steam server-list terms for republishing are UNVERIFIED: read them before enabling." />
        <FlagSwitch flag="directory_external_show" label="Show third-party servers on public pages" on={showOn}
          help="Off: public directory pages list Nxeon-hosted servers only, whatever has been ingested." />
      </div>

      <section className="space-y-3">
        <h2 className="section-label">Customer listings</h2>
        {listed.length === 0 && <EmptyState title="No opted-in listings" sub="A listing appears here when a customer switches on the Public Directory card in their game panel." />}
        {listed.map((s) => {
          const m = s.listingMeta;
          const hasMedia = !!(m?.imageUrl || m?.websiteUrl);
          return (
            <div key={s.id} className="card space-y-3 p-4">
              <div className="flex flex-wrap items-center gap-2">
                <h3 className="text-sm font-semibold">{s.label || s.name}</h3>
                <Badge tone="slate">{gname(s.gamePlan?.gameFamily)}</Badge>
                <Badge tone={s.status === "RUNNING" ? "green" : "slate"}>{s.status}</Badge>
                {m?.hidden && <Badge tone="red">Hidden</Badge>}
                {m?.featured && <Badge tone="green">Featured</Badge>}
                {hasMedia && <Badge tone={m!.mediaApproved ? "green" : "amber"}>{m!.mediaApproved ? "Media approved" : "Media pending"}</Badge>}
                <span className="font-mono text-xs text-slate-400">{s.subdomain ? `${s.subdomain}.${base}` : "no subdomain: not listed"}</span>
              </div>
              {m?.tagline && <p className="text-xs text-slate-300">Tagline: {m.tagline}</p>}
              {s.publicDescription && <p className="text-xs text-slate-400">{s.publicDescription}</p>}
              {hasMedia && (
                <div className="text-xs text-slate-400 space-y-1">
                  {m?.imageUrl && <p>Picture: <a className="underline" href={m.imageUrl} target="_blank" rel="noopener noreferrer nofollow">{m.imageUrl}</a></p>}
                  {m?.websiteUrl && <p>Website: <a className="underline" href={m.websiteUrl} target="_blank" rel="noopener noreferrer nofollow">{m.websiteUrl}</a></p>}
                </div>
              )}
              <ListingActions serverId={s.id} hidden={!!m?.hidden} featured={!!m?.featured} hasMedia={hasMedia} mediaApproved={!!m?.mediaApproved} />
            </div>
          );
        })}
      </section>

      <section className="space-y-3">
        <h2 className="section-label">Third-party servers (latest 40)</h2>
        {runs.length > 0 && (
          <div className="card p-4 text-xs text-slate-400">
