          </div>
        )}
        {ext.length === 0 ? <EmptyState title="Nothing ingested" sub="Run scripts/directory-ingest.ts (dry run first). See docs/DOCUMENTATION.md, Server directory." /> : (
          <div className="card overflow-x-auto p-0">
            <table className="w-full text-xs">
              <thead><tr className="text-left text-slate-400"><th className="p-2">Name</th><th className="p-2">Game</th><th className="p-2">Address</th><th className="p-2">Players</th><th className="p-2">Seen</th><th className="p-2"></th></tr></thead>
