// ── Admin moderation (requireArea("fleet"), same area as the other community-server tools) ─────────────

export async function adminModerateListing(
  serverId: string,
  action: "approve-media" | "reject-media" | "hide" | "unhide" | "feature" | "unfeature",
  note?: string,
): Promise<Result> {
  const admin = await requireArea("fleet");
  try {
    const exists = await db.server.findUnique({ where: { id: serverId }, select: { id: true } });
    if (!exists) return { ok: false, error: "Server not found." };
    const now = new Date();
    const stamp = { moderatedById: admin.id, moderatedAt: now };
    const n = cleanText(note, 200);
    const data =
      action === "approve-media" ? { mediaApproved: true, ...stamp }
      : action === "reject-media" ? { mediaApproved: false, imageUrl: null, websiteUrl: null, moderationNote: n, ...stamp }
      : action === "hide" ? { hidden: true, moderationNote: n, ...stamp }
      : action === "unhide" ? { hidden: false, ...stamp }
      : action === "feature" ? { featured: true, ...stamp }
      : { featured: false, ...stamp };
    await db.publicListingMeta.upsert({ where: { serverId }, create: { serverId, ...data }, update: data });
    await recordAudit(admin.id, `directory.moderate.${action}`, `server=${serverId}`);
    revalidatePath("/admin/directory");
    revalidatePath("/game-servers/directory");
    return { ok: true };
  } catch { return { ok: false, error: "Could not save." }; }
}

export async function adminHideExternal(id: string, hidden: boolean): Promise<Result> {
  const admin = await requireArea("fleet");
  try {
    await db.externalServer.update({ where: { id }, data: { hidden } });
    await recordAudit(admin.id, hidden ? "directory.external.hide" : "directory.external.unhide", `external=${id}`);
    revalidatePath("/admin/directory");
    return { ok: true };
  } catch { return { ok: false, error: "Could not save." }; }
}

const FLAGS = ["directory_ingest_enabled", "directory_external_show"] as const;
export async function adminSetDirectoryFlag(key: (typeof FLAGS)[number], value: boolean): Promise<Result> {
  const admin = await requireArea("fleet");
  if (!FLAGS.includes(key)) return { ok: false, error: "Unknown setting." };
  const { setSetting } = await import("./settings");
  await setSetting(key, value ? "true" : "false");
  await recordAudit(admin.id, "directory.flag", `${key}=${value}`);
  revalidatePath("/admin/directory");
  return { ok: true };
}
"use client";

import { useState, useTransition } from "react";
import { adminModerateListing, adminHideExternal, adminSetDirectoryFlag } from "@/lib/actions-listing";

type Act = "approve-media" | "reject-media" | "hide" | "unhide" | "feature" | "unfeature";

export function ListingActions({ serverId, hidden, featured, hasMedia, mediaApproved }: {
  serverId: string; hidden: boolean; featured: boolean; hasMedia: boolean; mediaApproved: boolean;
}) {
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  const run = (a: Act, note?: string) => start(async () => {
    const r = await adminModerateListing(serverId, a, note);
    setMsg(r.ok ? "Saved. Reload to see it." : r.error);
  });
  return (
    <div className="flex flex-wrap items-center gap-2">
      {hasMedia && !mediaApproved && <button className="btn-primary py-1 text-xs" disabled={pending} onClick={() => run("approve-media")}>Approve picture + link</button>}
      {hasMedia && <button className="btn-ghost py-1 text-xs" disabled={pending} onClick={() => confirm("Remove the picture and website link from this listing?") && run("reject-media", prompt("Note for the audit trail (optional)") ?? undefined)}>Reject picture + link</button>}
      <button className="btn-ghost py-1 text-xs" disabled={pending} onClick={() => run(featured ? "unfeature" : "feature")}>{featured ? "Unfeature" : "Feature"}</button>
      {hidden
        ? <button className="btn-ghost py-1 text-xs" disabled={pending} onClick={() => run("unhide")}>Unhide</button>
        : <button className="btn-ghost py-1 text-xs text-red-300" disabled={pending} onClick={() => confirm("Hide this listing from every public page?") && run("hide", prompt("Reason (optional, kept internally)") ?? undefined)}>Hide listing</button>}
      {msg && <span className="text-xs text-slate-300">{msg}</span>}
    </div>
  );
}

export function ExternalActions({ id, hidden }: { id: string; hidden: boolean }) {
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  return (
    <span className="inline-flex items-center gap-2">
      <button className="btn-ghost py-0.5 text-xs" disabled={pending} onClick={() => start(async () => { const r = await adminHideExternal(id, !hidden); setMsg(r.ok ? "Saved." : r.error); })}>{hidden ? "Unhide" : "Hide"}</button>
      {msg && <span className="text-xs text-slate-400">{msg}</span>}
    </span>
  );
}

export function FlagSwitch({ flag, label, help, on }: { flag: "directory_ingest_enabled" | "directory_external_show"; label: string; help: string; on: boolean }) {
  const [pending, start] = useTransition();
  const [state, setState] = useState(on);
  const [msg, setMsg] = useState<string | null>(null);
  return (
    <div className="card flex items-start justify-between gap-4 p-4">
      <div>
        <h3 className="text-sm font-semibold">{label}</h3>
        <p className="mt-1 text-xs text-slate-400">{help}</p>
        {msg && <p className="mt-1 text-xs text-slate-300">{msg}</p>}
      </div>
      <button type="button" role="switch" aria-checked={state} disabled={pending}
        onClick={() => start(async () => {
          const next = !state;
          if (next && !confirm(`Turn on: ${label}?`)) return;
          const r = await adminSetDirectoryFlag(flag, next);
