/**
 * Public-directory blocklist matcher — PURE (no db, no network; unit-tested).
 *
 * Decides whether an external server's CONNECTION ADDRESS shows a competing
 * game-server host, so it can be kept off the directory. Nxeon-hosted and
 * opt-in Nxeon listings never go through this (and Nxeon's own domains can
 * never match, see NXEON_NEVER_BLOCK).
 *
 * Rule syntax (one per line in the admin Settings; `#` starts a comment):
 *   domain.tld       that domain AND every subdomain of it (label boundary:
 *                    `x.nitrado.net` matches, `notnitrado.net` does not)
 *   *.domain.tld     subdomains only, not the bare domain
 *   keyword:foo      `foo` appears inside the REGISTRABLE-DOMAIN label only
 *                    (the label left of the public suffix: `nitrado` in
 *                    `play.nitrado-eu.com`), never in subdomains, the TLD or
 *                    the path. So a community named "apex" on
 *                    `apex.fun`/`play.apex-community.com` is only hit by
 *                    `keyword:apex`, never by a default rule.
 *
 * Order: Nxeon-own domains -> ALLOW list -> block rules (default + extra).
 * Hostnames are normalised (lowercase, trailing dots removed, IDN -> punycode
 * so `xn--` and Unicode forms are the same host; a Unicode look-alike of a
 * brand is NOT the brand). IP literals have no domain to match: they are
 * allowed here and flagged `needsPtr`, so the INGEST job can reverse-resolve
 * them and call evaluateHost again with `ptr`. No ASN or IP-range blocking
 * exists (the repo has no ASN data) — by design.
 */
import { domainToASCII, domainToUnicode } from "node:url";
import { isIP } from "node:net";
import { DEFAULT_BLOCK_ENTRIES, type BlockEntry } from "./directory-blocklist-data";

/** Domains that can never be blocked, whatever any list says. */
export const NXEON_NEVER_BLOCK = ["nxeon.cloud", "nxeon.email", "nxeon.com", "nxeon.net"] as const;

export type RuleOrigin = "default" | "extra" | "allow";
export type Rule = {
  kind: "suffix" | "keyword";
  value: string;
  /** suffix only: `*.x` form (subdomains only). */
  wildcard: boolean;
  origin: RuleOrigin;
  provider: string | null;
  source: string | null;
  /** Stable id, e.g. `suffix:nitrado.net`, `suffix:*.nitrado.net`, `keyword:nitrado`. */
  id: string;
};
export type RuleSet = { block: Rule[]; allow: Rule[]; neverBlock: string[] };
export type RuleError = { line: number; text: string; error: string };

export type Verdict = {
  blocked: boolean;
  /** Normalised host the verdict is about (null when the input was unusable). */
  host: string | null;
  port: number | null;
  isIp: boolean;
  /** True for an IP literal that has not been given a PTR name yet. */
  needsPtr: boolean;
  /** Set when blocked. */
  rule: Rule | null;
  via: "host" | "ptr" | null;
  /** The name the rule actually matched (the host or the PTR name). */
  matched: string | null;
  /** Set when a block rule WOULD have matched but an allow rule / Nxeon domain overrode it. */
  allowedBy: string | null;
};

