  else if (v.allowedBy) summary = `ALLOWED: a block rule matched but ${v.allowedBy === "nxeon-own-domain" ? "this is an Nxeon domain (never blocked)" : `the allow list overrides it (${v.allowedBy.slice(6)})`}`;
