import { Resolver } from "node:dns/promises";

/**
 * Reverse-DNS (PTR) lookups for IP-only directory rows. INGEST TIME ONLY —
 * never call this from a page render. Bounded three ways: a per-lookup timeout,
 * a concurrency cap and a hard cap on lookups per run; anything over budget or
 * failing simply yields no PTR (the row is then judged on its host alone).
 * The reverse function is injectable so tests never touch the network.
 */
export type ReverseFn = (ip: string) => Promise<string[]>;

export const PTR_TIMEOUT_MS = 1500;
export const PTR_CONCURRENCY = 16;
export const PTR_MAX_LOOKUPS = 3000;
export const PTR_TTL_MS = 30 * 86_400_000;

export function systemReverse(timeoutMs = PTR_TIMEOUT_MS): ReverseFn {
  const resolver = new Resolver({ timeout: timeoutMs, tries: 1 });
  return (ip) => resolver.reverse(ip);
}

async function withTimeout<T>(p: Promise<T>, ms: number): Promise<T | null> {
  let t: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([p, new Promise<null>((r) => { t = setTimeout(() => r(null), ms); })]);
  } finally { if (t) clearTimeout(t); }
}

/** ip -> first PTR name, or null (none / failed / timed out / over budget). */
export async function resolvePtrs(ips: string[], opts: { reverse?: ReverseFn; timeoutMs?: number; concurrency?: number; maxLookups?: number } = {}): Promise<Map<string, string | null>> {
  const timeoutMs = opts.timeoutMs ?? PTR_TIMEOUT_MS;
  const reverse = opts.reverse ?? systemReverse(timeoutMs);
  const work = [...new Set(ips)].slice(0, opts.maxLookups ?? PTR_MAX_LOOKUPS);
  const out = new Map<string, string | null>();
  let next = 0;
  const worker = async () => {
    while (next < work.length) {
      const ip = work[next++];
      try {
        const names = await withTimeout(reverse(ip), timeoutMs);
        out.set(ip, names && names.length ? names[0] : null);
      } catch { out.set(ip, null); }
    }
  };
  await Promise.all(Array.from({ length: Math.max(1, Math.min(opts.concurrency ?? PTR_CONCURRENCY, work.length || 1)) }, worker));
  return out;
}
