import { db } from "@/lib/db";
import { getSetting } from "@/lib/settings";
import { buildRuleSet, evaluateHost, describeVerdict, type RuleSet, type RuleError } from "@/lib/directory-blocklist";

/**
 * Database side of the competitor-host blocklist. The rules come from the
 * shipped default list + two admin Settings (directory_blocked_hosts_extra /
 * _allow). Nxeon's own play domain is added to the never-block list.
 */
export async function loadRuleSet(): Promise<{ set: RuleSet; errors: RuleError[] }> {
  const [extraText, allowText, freeDomain] = await Promise.all([
    getSetting("directory_blocked_hosts_extra", "").catch(() => ""),
    getSetting("directory_blocked_hosts_allow", "").catch(() => ""),
    getSetting("free_minecraft_domain", "play.nxeon.cloud").catch(() => "play.nxeon.cloud"),
  ]);
  return buildRuleSet({ extraText, allowText, neverBlock: [freeDomain] });
}

/**
 * Re-judge every stored external row against the CURRENT rules using the host
 * and the PTR name stored at ingest (no network). Called after the admin edits
 * the lists, so rows blocked by a removed/allow-listed rule come back and new
 * blocks are recorded. Returns how many rows changed state.
 */
export async function reevaluateExternalBlocks(): Promise<{ checked: number; nowBlocked: number; unblocked: number }> {
  const { set } = await loadRuleSet();
  const rows = await db.externalServer.findMany({ select: { id: true, host: true, port: true, ptrName: true, blockedReason: true, blockedRule: true } });
  let nowBlocked = 0, unblocked = 0;
  const updates: { id: string; reason: string | null; rule: string | null }[] = [];
  for (const r of rows) {
    const v = evaluateHost(r.host, r.port, set, { ptr: r.ptrName });
    const reason = describeVerdict(v), rule = v.rule?.id ?? null;
    if (reason === r.blockedReason && rule === r.blockedRule) continue;
    if (reason && !r.blockedReason) nowBlocked++;
    if (!reason && r.blockedReason) unblocked++;
    updates.push({ id: r.id, reason, rule });
  }
  for (let i = 0; i < updates.length; i += 200) {
    await db.$transaction(updates.slice(i, i + 200).map((u) => db.externalServer.update({ where: { id: u.id }, data: { blockedReason: u.reason, blockedRule: u.rule } })));
  }
  return { checked: rows.length, nowBlocked, unblocked };
}
