const run = opts.apply ? await db.directoryIngestRun.create({ data: { source: "valve", game } }) : null;
try {
  const fetched = await fetchValveList(game, { key: opts.key, limit: opts.limit, fetchImpl: opts.fetchImpl });
  const nxKeys = await nxeonConnectionKeys();
  const { keep, dup } = splitDuplicates<ExternalCandidate>(fetched, nxKeys);
  let inserted = 0, updated = 0, pruned = 0, blocked = 0;
  // Competitor-host blocklist. Blocked rows are STORED with a verdict (so admins can see what
  // was dropped and why, and re-evaluate when rules change) and filtered out of every display query.
  const { set } = await loadRuleSet();
  const existingRows = await db.externalServer.findMany({ where: { source: "valve", game }, select: { id: true, sourceKey: true, host: true, ptrName: true, ptrCheckedAt: true } });
  const cache: PtrCache = new Map(existingRows.map((r) => [r.host, { ptrName: r.ptrName, checkedAt: r.ptrCheckedAt }]));
  const judged = await judgeCandidates(keep, set, cache, { reverse: opts.reverse });
  blocked = judged.filter((j) => j.blockedReason).length;
  if (opts.apply) {
    const existing = new Map(existingRows.map((r) => [r.sourceKey, r.id]));
    const now = new Date();
    for (let i = 0; i < judged.length; i += 100) {
      await db.$transaction(judged.slice(i, i + 100).map(({ cand: c, ptrName, ptrCheckedAt, blockedReason, blockedRule }) => {
        const data = {
          blockedReason, blockedRule, ptrName, ptrCheckedAt,
          game: c.game, name: c.name, host: c.host, ip: c.ip, port: c.port, queryPort: c.queryPort, map: c.map,
          players: c.players, maxPlayers: c.maxPlayers, version: c.version, tags: c.tags,
          connKey: c.connKey, ipKey: c.ipKey, lastSeenAt: now,
        };
        if (existing.has(c.sourceKey)) updated++; else inserted++;
        return db.externalServer.upsert({
          where: { source_sourceKey: { source: "valve", sourceKey: c.sourceKey } },
          create: { source: "valve", sourceKey: c.sourceKey, ...data }, update: data,
        });
      }));
    }
    // Rows that now collide with something Nxeon hosts are removed (they were listed before we hosted them).
    const gone = await db.externalServer.deleteMany({
      where: { source: "valve", game, OR: [{ lastSeenAt: { lt: new Date(Date.now() - PRUNE_AFTER_DAYS * 86_400_000) } }, { connKey: { in: [...nxKeys] } }] },
    });
    pruned = gone.count;

