// ── Competitor-host blocklist (admin lists + live tester) ─────────────────────────────────────────────

const LIST_MAX = 20_000;

/** Save the extra-block and allow lists. Invalid lines are rejected (nothing is saved) with line numbers. */
export async function adminSaveDirectoryBlocklist(extraText: string, allowText: string): Promise<Result & { changed?: { nowBlocked: number; unblocked: number } }> {
  const admin = await requireArea("fleet");
  const extra = String(extraText ?? ""), allow = String(allowText ?? "");
  if (extra.length > LIST_MAX || allow.length > LIST_MAX) return { ok: false, error: "A list is too long." };
  const { buildRuleSet } = await import("./directory-blocklist");
  const { errors } = buildRuleSet({ extraText: extra, allowText: allow });
  if (errors.length) return { ok: false, error: errors.slice(0, 5).map((e) => `Line ${e.line} (${e.text}): ${e.error}`).join(" | ") };
  try {
    const { setSetting } = await import("./settings");
    await setSetting("directory_blocked_hosts_extra", extra.trim());
    await setSetting("directory_blocked_hosts_allow", allow.trim());
    await recordAudit(admin.id, "directory.blocklist.save", `extra=${extra.split("\\n").filter(Boolean).length} lines, allow=${allow.split("\\n").filter(Boolean).length} lines`);
    const { reevaluateExternalBlocks } = await import("./directory-blocklist-db");
    const r = await reevaluateExternalBlocks().catch(() => ({ nowBlocked: 0, unblocked: 0 }));
    revalidatePath("/admin/directory");
    revalidatePath("/game-servers/directory");
    return { ok: true, changed: { nowBlocked: r.nowBlocked, unblocked: r.unblocked } };
  } catch { return { ok: false, error: "Could not save." }; }
}

/** Re-judge every stored row with the current rules (no network). */
export async function adminReevaluateDirectoryBlocks(): Promise<Result & { nowBlocked?: number; unblocked?: number }> {
  await requireArea("fleet");
  try {
    const { reevaluateExternalBlocks } = await import("./directory-blocklist-db");
    const r = await reevaluateExternalBlocks();
    revalidatePath("/admin/directory");
    return { ok: true, nowBlocked: r.nowBlocked, unblocked: r.unblocked };
  } catch { return { ok: false, error: "Could not re-evaluate." }; }
}

/**
 * Live tester: judge one address with the SAVED rules, or with unsaved textarea
 * contents (`draft`) so an admin can try a rule before saving it. For an IP,
 * one bounded reverse-DNS lookup is made (admin-initiated, never from a page render).
 */
export async function adminTestDirectoryAddress(input: string, draft?: { extra: string; allow: string }): Promise<{ ok: true; summary: string; blocked: boolean; ptr: string | null } | { ok: false; error: string }> {
  await requireArea("fleet");
  const { splitHostPort, testAddress, buildRuleSet } = await import("./directory-blocklist");
  const hp = splitHostPort(String(input ?? ""));
  if (!hp) return { ok: false, error: "Not a valid address. Use host, host:port or ip:port." };
  let set;
  if (draft) {
    const b = buildRuleSet({ extraText: String(draft.extra).slice(0, LIST_MAX), allowText: String(draft.allow).slice(0, LIST_MAX) });
    if (b.errors.length) return { ok: false, error: `Fix the list first: line ${b.errors[0].line}: ${b.errors[0].error}` };
    set = b.set;
  } else set = (await (await import("./directory-blocklist-db")).loadRuleSet()).set;
  let ptr: string | null = null;
  const first = testAddress(input, set);
  if (first.ok && first.verdict.needsPtr) {
    const { resolvePtrs } = await import("./directory-ingest/ptr");
    ptr = (await resolvePtrs([first.verdict.host!], { maxLookups: 1 })).get(first.verdict.host!) ?? null;
  }
  const r = ptr ? testAddress(input, set, ptr) : first;
  if (!r.ok) return r;
  return { ok: true, summary: ptr ? `${r.summary} [reverse DNS: ${ptr}]` : r.summary, blocked: r.verdict.blocked, ptr };
}
'''
open(p,'w').write(s)
EOF
