"use server";

/**
 * Owner-side showcase extras for a server's opt-in public listing (mkt-031),
 * plus the ADMIN moderation actions for them. The opt-in itself is still
 * togglePublicListing (lib/actions-game-control.ts); nothing here can make a
 * server public.
 *
 * Moderation model: tagline and description are plain text and show at once.
 * A picture URL and a website URL are customer-supplied https links and are
 * NEVER rendered until an admin approves them; editing either one resets the
 * approval. An admin can hide a listing entirely (`hidden`) or feature it.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { requireArea } from "./rbac";
import { recordAudit } from "./audit";
import { checkRateLimit } from "./rate-limit";
import { cleanText, validHttpsUrl, submissionKit } from "./server-directory";

