"use client";

import { useState, useTransition } from "react";
import { adminSaveDirectoryBlocklist, adminReevaluateDirectoryBlocks, adminTestDirectoryAddress } from "@/lib/actions-listing";

/** Editable extra-block + allow lists, with a live "type an address, see allowed/blocked and why" tester. */
export function BlocklistPanel({ extra: extra0, allow: allow0 }: { extra: string; allow: string }) {
  const [extra, setExtra] = useState(extra0);
  const [allow, setAllow] = useState(allow0);
  const [addr, setAddr] = useState("");
  const [result, setResult] = useState<{ text: string; blocked: boolean } | null>(null);
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const dirty = extra !== extra0 || allow !== allow0;
  const ta = "input w-full font-mono text-xs";
  return (
    <div className="card space-y-4 p-4">
      <div>
        <h3 className="text-sm font-semibold">Block other game hosts</h3>
        <p className="mt-1 text-xs text-slate-400">
          Third-party servers whose connection address shows another game-hosting company are kept off every public page. A built-in list covers the well-known hosts;
          add more here. One rule per line: <code>domain.tld</code> (that domain and its subdomains), <code>*.domain.tld</code> (subdomains only) or <code>keyword:foo</code> (inside the
          registered-domain name only, at least 4 characters). The allow list overrides any block, for false positives. IP-only servers are judged by their reverse-DNS name, looked up when they are ingested.
        </p>
      </div>
      <div className="grid gap-4 lg:grid-cols-2">
        <label className="space-y-1 text-xs text-slate-300">Extra blocked hosts
          <textarea className={ta} rows={6} value={extra} onChange={(e) => setExtra(e.target.value)} placeholder={"examplehost.com\n*.examplehost.net\nkeyword:examplehost"} />
        </label>
        <label className="space-y-1 text-xs text-slate-300">Always allow (overrides blocks)
          <textarea className={ta} rows={6} value={allow} onChange={(e) => setAllow(e.target.value)} placeholder={"friendly-community.com"} />
        </label>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <button className="btn-primary py-1 text-xs" disabled={pending || !dirty} onClick={() => start(async () => {
          const r = await adminSaveDirectoryBlocklist(extra, allow);
          setMsg(r.ok ? `Saved. ${r.changed?.nowBlocked ?? 0} stored rows newly blocked, ${r.changed?.unblocked ?? 0} released. Reload to see counts.` : r.error);
        })}>Save lists</button>
        <button className="btn-ghost py-1 text-xs" disabled={pending} onClick={() => start(async () => {
          const r = await adminReevaluateDirectoryBlocks();
          setMsg(r.ok ? `Re-evaluated: ${r.nowBlocked} newly blocked, ${r.unblocked} released.` : r.error);
        })}>Re-evaluate stored rows</button>
        {msg && <span className="text-xs text-slate-300">{msg}</span>}
      </div>
      <div className="space-y-2 border-t border-white/[0.06] pt-3">
        <h4 className="text-xs font-semibold text-slate-200">Tester (uses the lists above, even unsaved)</h4>
        <form className="flex flex-wrap gap-2" onSubmit={(e) => {
          e.preventDefault();
          start(async () => {
            const r = await adminTestDirectoryAddress(addr, { extra, allow });
            setResult(r.ok ? { text: r.summary, blocked: r.blocked } : { text: r.error, blocked: false });
          });
        }}>
          <input className="input flex-1 font-mono text-xs" value={addr} onChange={(e) => setAddr(e.target.value)} placeholder="play.example.com:25565 or 203.0.113.7:2456" />
          <button className="btn-ghost py-1 text-xs" disabled={pending || !addr.trim()}>Test</button>
        </form>
        {result && <p className={`text-xs ${result.blocked ? "text-red-300" : "text-slate-300"}`}>{result.text}</p>}
      </div>
    </div>
  );
}
EOF
