import assert from "node:assert/strict";
import {
  buildRuleSet, evaluateHost, parseRuleText, testAddress, splitHostPort, normalizeName, registrableLabel, isRowBlocked, describeVerdict,
} from "../lib/directory-blocklist";
import { DEFAULT_BLOCK_ENTRIES } from "../lib/directory-blocklist-data";
import { resolvePtrs } from "../lib/directory-ingest/ptr";
import { judgeCandidates, ptrFresh, type PtrCache } from "../lib/directory-ingest/run";
import { filterExternalRows } from "../lib/server-directory-data";

const { set } = buildRuleSet();
const blocked = (h: string, o: Parameters<typeof evaluateHost>[3] = {}, s = set) => evaluateHost(h, 25565, s, o).blocked;

test("suffix match only on label boundaries, case-insensitive, trailing dot", () => {
  assert.ok(blocked("nitrado.net"));
  assert.ok(blocked("play.NITRADO.net."));
  assert.ok(blocked("a.b.shockbyte.com"));
  assert.ok(!blocked("notnitrado.net"));
  assert.ok(!blocked("nitrado.net.evil.example"));
  assert.ok(!blocked("shockbyte.com.au")); // different registrable domain; label keyword handled below
});

test("keyword hits the registrable label only, never subdomains or the TLD", () => {
  assert.ok(blocked("play.shockbyte-eu.com")); // brand inside the registrable label
  assert.ok(!blocked("shockbyte.community-site.com")); // brand only in a subdomain
  assert.ok(!blocked("shockwave.gg"));
  assert.ok(!blocked("apex.fun"));
  assert.ok(!blocked("play.apexcommunity.com"));
  assert.ok(!blocked("mc.example.com"));
});

test("registrable label with two-part public suffixes", () => {
  assert.equal(registrableLabel("play.gtxgaming.co.uk"), "gtxgaming");
  assert.equal(registrableLabel("a.example.com"), "example");
  assert.ok(blocked("x.gtxgaming.co.uk"));
});

test("admin keyword rule: apex community only blocked when an admin says so", () => {
  const { set: s2 } = buildRuleSet({ extraText: "keyword:apexfans" });
  assert.ok(blocked("play.apexfans.net", {}, s2));
  assert.ok(!blocked("play.apexfans.net"));
  assert.ok(!blocked("apex.fun", {}, s2));
});

test("punycode and unicode forms are the same host; look-alikes are not the brand", () => {
  const { set: s2 } = buildRuleSet({ extraText: "bücher-host.de" });
  assert.ok(blocked("play.xn--bcher-host-4db.de", {}, s2) === (normalizeName("bücher-host.de") === "xn--bcher-host-4db.de"));
  assert.ok(blocked("play.bücher-host.de", {}, s2));
  assert.ok(!blocked("ѕhockbyte.com")); // Cyrillic s
  assert.ok(!blocked("xn--hockbyte-9ve.com"));
});

test("IPv4 and IPv6 literals: no hostname match, flagged needsPtr; PTR name drives the verdict", () => {
  const v4 = evaluateHost("203.0.113.7", 2456, set);
  assert.deepEqual([v4.blocked, v4.isIp, v4.needsPtr], [false, true, true]);
  assert.equal(evaluateHost("[2001:db8::1]", 2456, set).isIp, true);
  assert.equal(evaluateHost("2001:db8::1", 2456, set).needsPtr, true);
  const viaPtr = evaluateHost("203.0.113.7", 2456, set, { ptr: "ded1234.Nitrado.net." });
  assert.equal(viaPtr.blocked, true);
  assert.equal(viaPtr.via, "ptr");
  assert.equal(viaPtr.rule?.id, "suffix:nitrado.net");
  assert.ok(!evaluateHost("203.0.113.7", 2456, set, { ptr: "static.1.113.0.203.clients.your-server.de" }).blocked); // Hetzner: generic cloud
  assert.ok(!evaluateHost("203.0.113.7", 2456, set, { ptr: "ec2-1-2-3-4.compute.amazonaws.com" }).blocked);
});

test("allow list overrides default and extra blocks, for hosts and PTR names", () => {
  const { set: s2 } = buildRuleSet({ allowText: "friend.nitrado.net\n*.ok.example.com", extraText: "bad.example.com\nok.example.com" });
  assert.ok(!blocked("friend.nitrado.net", {}, s2));
  assert.ok(!blocked("play.friend.nitrado.net", {}, s2));
  assert.ok(blocked("other.nitrado.net", {}, s2));
  assert.ok(!blocked("a.ok.example.com", {}, s2));
  assert.ok(blocked("ok.example.com", {}, s2)); // wildcard allow does not cover the bare domain
  assert.ok(!evaluateHost("1.2.3.4", 1, s2, { ptr: "x.friend.nitrado.net" }).blocked);
  assert.equal(evaluateHost("friend.nitrado.net", 1, s2).allowedBy, "allow:suffix:friend.nitrado.net");
});

test("Nxeon domains are never blocked, even by an admin rule or keyword", () => {
  const { set: s2 } = buildRuleSet({ extraText: "nxeon.cloud\nkeyword:nxeon", neverBlock: ["play.example-nx.test"] });
  for (const h of ["play.nxeon.cloud", "x.nxeon.cloud", "nxeon.cloud", "mail.nxeon.email", "srv.play.nxeon.cloud"]) assert.equal(blocked(h, {}, s2), false, h);
  assert.equal(evaluateHost("x.nxeon.cloud", 1, s2).allowedBy, "nxeon-own-domain");
  assert.equal(blocked("1.2.3.4", { ptr: "vm1.nxeon.cloud" }, s2), false);
});

test("no default entry matches Nxeon; none is a generic cloud/VPS provider", () => {
  for (const e of DEFAULT_BLOCK_ENTRIES) {
    assert.ok(e.provider && e.source.startsWith("https://"), e.value);
    assert.ok(!/nxeon/.test(e.value), e.value);
    assert.ok(!/(hetzner|ovh|digitalocean|amazonaws|linode|vultr|google|azure|contabo|hostinger|cloudflare|your-server|hstgr)/.test(e.value), e.value);
    if (e.kind === "keyword") assert.ok(e.value.length >= 6, `keyword too short: ${e.value}`);
  }
  for (const h of ["play.nxeon.cloud", "x.your-server.de", "vps.ovh.net", "srv1.hstgr.cloud"]) assert.equal(blocked(h), false, h);
});

test("every shipped brand domain is blocked, with the provider in the reason", () => {
  for (const e of DEFAULT_BLOCK_ENTRIES.filter((x) => x.kind === "suffix")) {
    const v = evaluateHost(`mc1.${e.value}`, 25565, set);
    assert.ok(v.blocked, e.value);
    assert.match(describeVerdict(v)!, new RegExp(e.provider.replace(/[-]/g, "\\-")));
  }
});

test("rule parsing: comments, blanks, wildcard, errors, dedupe", () => {
  const { rules, errors } = parseRuleText("# hi\n\nExample.COM  # trailing\n*.example.net\nkeyword:Hostbrand\nkeyword:ab\nnot a domain\ncom\nexample.com\nhttp://x.com/path", "extra");
  assert.deepEqual(rules.map((r) => r.id), ["suffix:example.com", "suffix:*.example.net", "keyword:hostbrand"]);
  assert.deepEqual(errors.map((e) => e.line), [5, 6, 7, 9]);
});

test("splitHostPort / normalizeName", () => {
  assert.deepEqual(splitHostPort("PLAY.Example.com:25566"), { host: "PLAY.Example.com", port: 25566 });
  assert.deepEqual(splitHostPort("steam://play.example.com:27015/x"), { host: "play.example.com", port: 27015 });
  assert.deepEqual(splitHostPort("[2001:db8::1]:2456"), { host: "2001:db8::1", port: 2456 });
  assert.deepEqual(splitHostPort("2001:db8::1"), { host: "2001:db8::1", port: null });
  assert.equal(splitHostPort("host:99999"), null);
  assert.equal(normalizeName("a b"), null);
  assert.equal(normalizeName(""), null);
});

test("admin tester logic", () => {
  const r = testAddress("PLAY.Nitrado.net:2456", set);
  assert.ok(r.ok && r.verdict.blocked && /^BLOCKED by suffix:nitrado\.net \(Nitrado\)/.test(r.summary));
  const ok = testAddress("play.example.com:25565", set);
  assert.ok(ok.ok && !ok.verdict.blocked && /no rule matches/.test(ok.summary));
  const ip = testAddress("203.0.113.7:2456", set);
  assert.ok(ip.ok && ip.verdict.needsPtr && /reverse-DNS/.test(ip.summary));
  const ip2 = testAddress("203.0.113.7:2456", set, "x.gportal.com");
  assert.ok(ip2.ok && ip2.verdict.blocked);
  const nx = testAddress("play.nxeon.cloud", buildRuleSet({ extraText: "nxeon.cloud" }).set);
  assert.ok(nx.ok && !nx.verdict.blocked && /Nxeon domain/.test(nx.summary));
  assert.equal(testAddress("", set).ok, false);
});

