test("ptr resolver: timeout, failure, concurrency cap and lookup budget", async () => {
  let inflight = 0, peak = 0;
  const reverse = async (ip: string) => {
    inflight++; peak = Math.max(peak, inflight);
    await new Promise((r) => setTimeout(r, 5));
    inflight--;
    if (ip === "10.0.0.2") throw new Error("ENOTFOUND");
    if (ip === "10.0.0.3") await new Promise((r) => setTimeout(r, 200));
    return [`h-${ip}.nitrado.net`];
  };
  const ips = Array.from({ length: 12 }, (_, i) => `10.0.0.${i + 1}`);
  const out = await resolvePtrs(ips, { reverse, timeoutMs: 50, concurrency: 3 });
  assert.ok(peak <= 3 + 1); // the timed-out call may still be settling
  assert.equal(out.get("10.0.0.1"), "h-10.0.0.1.nitrado.net");
  assert.equal(out.get("10.0.0.2"), null);
  assert.equal(out.get("10.0.0.3"), null);
  const capped = await resolvePtrs(ips, { reverse: async () => ["a.b.c"], maxLookups: 4 });
  assert.equal(capped.size, 4);
});

test("ingest: hostnames judged directly, IPs via PTR, cache reused, verdict stored", async () => {
  const calls: string[] = [];
  const reverse = async (ip: string) => { calls.push(ip); return ip === "203.0.113.9" ? ["srv9.g-portal.com"] : ["host.example.org"]; };
  const cands = [
    { host: "play.shockbyte.com", port: 25565 },
    { host: "203.0.113.9", port: 2456 },
    { host: "203.0.113.10", port: 2456 },
    { host: "203.0.113.11", port: 2456 },
    { host: "mc.community.net", port: 25565 },
  ];
  const now = new Date();
  const cache: PtrCache = new Map([["203.0.113.11", { ptrName: "old.pebblehost.com", checkedAt: new Date(now.getTime() - 86_400_000) }]]);
  const out = await judgeCandidates(cands, set, cache, { reverse, now });
  assert.deepEqual(calls.sort(), ["203.0.113.10", "203.0.113.9"]); // .11 was cached
  assert.deepEqual(out.map((o) => !!o.blockedReason), [true, true, false, true, false]);
  assert.equal(out[0].blockedRule, "suffix:shockbyte.com");
  assert.match(out[1].blockedReason!, /reverse DNS srv9\.g-portal\.com/);
  assert.equal(out[1].ptrName, "srv9.g-portal.com");
  assert.equal(out[2].ptrName, "host.example.org");
  assert.equal(out[0].ptrCheckedAt, null); // hostname rows never get a PTR check
  assert.ok(ptrFresh({ ptrName: null, checkedAt: new Date(now.getTime() - 2 * 86_400_000) }, now.getTime()) === false);
  assert.ok(ptrFresh({ ptrName: "x.y", checkedAt: new Date(now.getTime() - 2 * 86_400_000) }, now.getTime()));
});

test("display filter re-evaluates live rules over stored rows (rule change needs no re-ingest)", () => {
  const rows = [
    { host: "play.example.com", port: 1, ptrName: null },
    { host: "203.0.113.9", port: 1, ptrName: "a.gtxgaming.co.uk" },
    { host: "play.newhost.io", port: 1, ptrName: null },
    { host: "203.0.113.10", port: 1, ptrName: null },
  ];
  assert.deepEqual(filterExternalRows(rows, set).map((r) => r.host), ["play.example.com", "play.newhost.io", "203.0.113.10"]);
  const { set: later } = buildRuleSet({ extraText: "newhost.io" });
  assert.deepEqual(filterExternalRows(rows, later).map((r) => r.host), ["play.example.com", "203.0.113.10"]);
  const { set: allowed } = buildRuleSet({ allowText: "gtxgaming.co.uk" });
  assert.equal(filterExternalRows(rows, allowed).length, 4);
  assert.equal(filterExternalRows(rows, null).length, 4);
  assert.ok(isRowBlocked(rows[1], set));
});
